package com.nexuspc.catalog.product;
import com.nexuspc.catalog.category.*; import com.nexuspc.catalog.dto.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*;
@Service public class ProductService { private final ProductRepository repo; private final CategoryRepository categories; public ProductService(ProductRepository repo,CategoryRepository categories){this.repo=repo;this.categories=categories;}
 public Page<ProductResponse> search(String q,String category,boolean featured,boolean bestseller,boolean fresh,BigDecimal min,BigDecimal max,String brand,Pageable page){return repo.search(blank(q),blank(category),featured,bestseller,fresh,min,max,blank(brand),page).map(this::response);}
 public ProductResponse get(String slug){return response(repo.findBySlug(slug).orElseThrow(()->new NoSuchElementException("Product not found")));}
 @Transactional public ProductResponse create(ProductRequest r){if(repo.existsBySlug(r.slug())||repo.existsBySku(r.sku()))throw new IllegalArgumentException("Product slug or SKU already exists");return response(repo.save(toEntity(r)));}
 @Transactional public ProductResponse update(Long id,ProductRequest r){Product p=repo.findById(id).orElseThrow(()->new NoSuchElementException("Product not found"));if((!p.getSlug().equals(r.slug())&&repo.existsBySlug(r.slug()))||(!p.getSku().equals(r.sku())&&repo.existsBySku(r.sku())))throw new IllegalArgumentException("Product slug or SKU already exists");p.update(r.slug(),r.name(),r.brand(),r.sku(),category(r.categoryId()),r.description(),r.shortDescription(),images(r.images()),r.price(),r.originalPrice(),r.stockCount(),r.rating(),r.reviewCount(),r.warranty(),r.specifications(),r.tags(),r.featured(),r.bestseller(),r.isNew());return response(p);}
 @Transactional public void delete(Long id){if(!repo.existsById(id))throw new NoSuchElementException("Product not found");repo.deleteById(id);}
 private Product toEntity(ProductRequest r){return new Product(r.slug(),r.name(),r.brand(),r.sku(),category(r.categoryId()),r.description(),r.shortDescription(),images(r.images()),r.price(),r.originalPrice(),r.stockCount(),r.rating(),r.reviewCount(),r.warranty(),r.specifications(),r.tags(),r.featured(),r.bestseller(),r.isNew());}
 private Category category(Long id){return categories.findById(id).orElseThrow(()->new NoSuchElementException("Category not found"));} private List<ProductImage> images(List<ImageRequest> x){return x==null?new ArrayList<>():x.stream().map(i->new ProductImage(i.url(),i.alt())).toList();} private String blank(String s){return s==null||s.isBlank()?null:s;}
 public ProductResponse response(Product p){Integer discount=null;if(p.getOriginalPrice()!=null&&p.getOriginalPrice().signum()>0)discount=p.getOriginalPrice().subtract(p.getPrice()).multiply(BigDecimal.valueOf(100)).divide(p.getOriginalPrice(),0,RoundingMode.HALF_UP).intValue();String status=p.getStockCount()<=0?"out_of_stock":p.getStockCount()<10?"low_stock":"in_stock";var imgs=new ArrayList<ProductResponse.ImageResponse>();int n=0;for(ProductImage i:p.getImages())imgs.add(new ProductResponse.ImageResponse(String.valueOf(++n),i.getUrl(),i.getAlt()));return new ProductResponse(p.getId(),p.getSlug(),p.getName(),p.getBrand(),p.getCategory().getSlug(),p.getCategory().getName(),p.getSku(),p.getDescription(),p.getShortDescription(),imgs,p.getPrice(),p.getOriginalPrice(),discount,status,p.getStockCount(),p.getRating(),p.getReviewCount(),p.getWarranty(),p.getSpecifications(),p.getTags(),p.isFeatured(),p.isBestseller(),p.isNewProduct(),p.getCreatedAt(),p.getUpdatedAt());}
}
